1	// The requirements harness's browser: pinned Playwright Chromium, a hermetic
2	// fake origin served from disk, and every nondeterministic input replaced —
3	// clock, location, randomness, network (fonts, Leaflet, map tiles, geocoding,
4	// live data). Every UI case (screen and behavior kinds alike) gets its page
5	// from here, so "deterministic" is decided once, not per case.
6	//
7	// The page is served from a FAKE origin (http://edfringenow.req/), fulfilled
8	// entirely from the repo working tree + committed fixtures via route
9	// interception — no HTTP server process, no port, nothing off-disk. Any request
10	// the routing table doesn't recognise is aborted, so a new external dependency
11	// in the product breaks the suite loudly instead of adding hidden network.
12	"use strict";
13	
14	const fs = require("node:fs");
15	const os = require("node:os");
16	const path = require("node:path");
17	const { execSync } = require("node:child_process");
18	const { pathToFileURL } = require("node:url");
19	
20	const REPO_ROOT = path.join(__dirname, "..", "..", "..", "..");
21	const VENDOR_DIR = path.join(__dirname, "vendor");
22	const FIXTURES_DIR = path.join(__dirname, "..", "fixtures");
23	const { REFERENCE_NOW_UTC_MS, TIMEZONE, LOCALE, GEOLOCATION } = require("../reference-now");
24	
25	// Rendering is only comparable against the committed goldens when the exact
26	// same Chromium rasterises it. This is the Playwright whose vendored browser
27	// the goldens were rendered with; the runner refuses to compare with any other.
28	const PINNED_PLAYWRIGHT = "1.56.1";
29	
30	// https, not http: geolocation only exists on secure origins. Routes are
31	// fulfilled before any real connection, so no certificate is involved.
32	const ORIGIN = "https://edfringenow.req";
33	
34	// The two committed viewports. A case says `viewport: "desktop"`; everything
35	// else about the screen (DPR 1, no touch) is fixed here.
36	const VIEWPORTS = {
37	  mobile: { width: 390, height: 844 },
38	  desktop: { width: 1280, height: 900 },
39	};
40	
41	const MIME = {
42	  ".html": "text/html; charset=utf-8",
43	  ".js": "text/javascript; charset=utf-8",
44	  ".mjs": "text/javascript; charset=utf-8",
45	  ".css": "text/css; charset=utf-8",
46	  ".json": "application/json; charset=utf-8",
47	  ".png": "image/png",
48	  ".svg": "image/svg+xml",
49	  ".webp": "image/webp",
50	  ".ico": "image/x-icon",
51	  ".woff2": "font/woff2",
52	  ".csv": "text/csv; charset=utf-8",
53	  ".txt": "text/plain; charset=utf-8",
54	};
55	
56	// Playwright resolves differently per environment: CI installs it into
57	// node_modules (a plain import), the Claude sandbox ships it globally beside a
58	// pre-provisioned browser. Try the local install first, then the global build
59	// by its ESM entry (the CJS index.js yields undefined named exports).
60	async function loadPlaywright() {
61	  try {
62	    return await import("playwright");
63	  } catch {
64	    /* no local install — fall through to the global build */
65	  }
66	  const guesses = ["/opt/node22/lib/node_modules/playwright/index.mjs"];
67	  try {
68	    guesses.push(path.join(execSync("npm root -g", { encoding: "utf8" }).trim(), "playwright", "index.mjs"));
69	  } catch {
70	    /* npm unavailable — the hardcoded guess still stands */
71	  }
72	  for (const g of guesses) {
73	    if (fs.existsSync(g)) return import(pathToFileURL(g).href);
74	  }
75	  throw new Error(
76	    "Playwright not found. Install the pinned version locally: npm i --no-save playwright@" +
77	      PINNED_PLAYWRIGHT +
78	      " && npx playwright install chromium"
79	  );
80	}
81	
82	function playwrightVersion() {
83	  const candidates = [
84	    path.join(REPO_ROOT, "node_modules", "playwright", "package.json"),
85	    "/opt/node22/lib/node_modules/playwright/package.json",
86	  ];
87	  for (const c of candidates) {
88	    if (fs.existsSync(c)) return JSON.parse(fs.readFileSync(c, "utf8")).version;
89	  }
90	  return null;
91	}
92	
93	// Deterministic Math.random for the page: mulberry32, fixed seed. Runs before
94	// any page script.
95	const SEEDED_RANDOM = `
96	  (() => {
97	    let s = 0xedf12026;
98	    Math.random = function () {
99	      s |= 0; s = (s + 0x6d2b79f5) | 0;
100	      let t = Math.imul(s ^ (s >>> 15), 1 | s);
101	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
102	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
103	    };
104	  })();
105	`;
106	
107	// Freeze every visual in flight: CSS animations/transitions land on their end
108	// state, the text caret never blinks, smooth scrolling is instant. Injected at
109	// document start so nothing renders un-frozen.
110	const FREEZE_CSS = `
111	  *, *::before, *::after {
112	    animation-duration: 0s !important;
113	    animation-delay: 0s !important;
114	    transition-duration: 0s !important;
115	    transition-delay: 0s !important;
116	    caret-color: transparent !important;
117	    scroll-behavior: auto !important;
118	  }
119	`;
120	
121	function fulfillFile(route, filePath, status = 200) {
122	  const ext = path.extname(filePath).toLowerCase();
123	  return route.fulfill({
124	    status,
125	    contentType: MIME[ext] || "application/octet-stream",
126	    body: fs.readFileSync(filePath),
127	  });
128	}
129	
130	// The routing table: URL → bytes, worked out once for the whole suite.
131	//   - our fake origin: fixtures override, then vendor, then the repo tree;
132	//   - Google Fonts CSS + unpkg Leaflet/markercluster: the committed vendor copies;
133	//   - OSM tiles: one committed fixture tile, whatever the coordinates;
134	//   - the geocoder: the committed fixture response (cases exercise "found");
135	//   - anything else: aborted.
136	async function routeAll(context, { dataDir, failData }) {
137	  await context.route("**/*", (route) => {
138	    const url = new URL(route.request().url());
139	    const { hostname, pathname } = url;
140	
141	    // Simulated outage: a case may declare URL substrings that must fail, to
142	    // drive the product's error states (a dead geocoder, a failed catalogue).
143	    if (failData && failData.some((s) => url.href.includes(s))) {
144	      return route.abort("failed");
145	    }
146	
147	    // Vendored assets, on ANY host: the fonts CSS is served from the Google
148	    // Fonts URL, so its url(/__vendor/…) references resolve against that host.
149	    if (pathname.startsWith("/__vendor/")) {
150	      const v = path.join(VENDOR_DIR, pathname.slice("/__vendor/".length).replace("fonts/", "fonts" + path.sep));
151	      if (fs.existsSync(v)) return fulfillFile(route, v);
152	      return route.abort();
153	    }
154	
155	    if (`${url.protocol}//${hostname}` === ORIGIN) {
156	      const rel = decodeURIComponent(pathname.replace(/^\/+/, "")) || "index.html";
157	      const withIndex = rel.endsWith("/") || rel === "" ? `${rel}index.html` : rel;
158	      // The version the footer/debug pill shows must not drift with releases.
159	      // (Stored as .fixture so no stray package.json lands in the tree.)
160	      if (withIndex === "package.json") {
161	        return route.fulfill({
162	          contentType: MIME[".json"],
163	          body: fs.readFileSync(path.join(FIXTURES_DIR, "package.json.fixture")),
164	        });
165	      }
166	      // Live data is replaced wholesale by the committed fixture snapshot.
167	      if (withIndex.startsWith("data/")) {
168	        const fixture = path.join(dataDir, withIndex.slice("data/".length));
169	        if (fs.existsSync(fixture)) return fulfillFile(route, fixture);
170	        return route.fulfill({ status: 404, contentType: "text/plain", body: "no fixture" });
171	      }
172	      const onDisk = path.join(REPO_ROOT, withIndex);
173	      if (fs.existsSync(onDisk) && fs.statSync(onDisk).isFile()) return fulfillFile(route, onDisk);
174	      const asDir = path.join(REPO_ROOT, withIndex, "index.html");
175	      if (fs.existsSync(asDir)) return fulfillFile(route, asDir);
176	      return route.fulfill({ status: 404, contentType: "text/plain", body: "not found" });
177	    }
178	
179	    if (hostname === "fonts.googleapis.com") {
180	      return fulfillFile(route, path.join(VENDOR_DIR, "fonts", "fonts.css"));
181	    }
182	    if (hostname === "unpkg.com") {
183	      if (pathname.includes("/dist/images/")) {
184	        const img = path.join(VENDOR_DIR, "leaflet", "images", path.basename(pathname));
185	        if (fs.existsSync(img)) return fulfillFile(route, img);
186	      }
187	      const known = {
188	        "leaflet.css": "leaflet.css",
189	        "leaflet.js": "leaflet.js",
190	        "MarkerCluster.css": "MarkerCluster.css",
191	        "leaflet.markercluster.js": "leaflet.markercluster.js",
192	      }[path.basename(pathname)];
193	      if (known) return fulfillFile(route, path.join(VENDOR_DIR, "leaflet", known));
194	      return route.abort();
195	    }
196	    if (hostname.endsWith("tile.openstreetmap.org")) {
197	      return fulfillFile(route, path.join(FIXTURES_DIR, "tile.png"));
198	    }
199	    if (hostname === "photon.komoot.io" || hostname === "nominatim.openstreetmap.org") {
200	      return fulfillFile(route, path.join(FIXTURES_DIR, "geocode.json"));
201	    }
202	    return route.abort();
203	  });
204	}
205	
206	// ------------------------------------------------------------- font jail --
207	// The web fonts are vendored, but they are not the only fonts on the page: any
208	// character they don't carry — an emoji, an arrow, a Cyrillic show title — is
209	// drawn by whatever the *machine* has installed. That made the goldens a
210	// record of the renderer's font set, and CI's set is not the sandbox's: the
211	// walk-time line ("🚶 5 min · £16") measured a different width there and
212	// wrapped, making every card one line taller.
213	//
214	// So the harness gives Chromium its own fontconfig world: a generated config
215	// whose only font directory is `vendor/systemfonts/`, with the generic
216	// families aliased into it. Nothing installed on the host can reach the page.
217	const SYSTEM_FONTS_DIR = path.join(VENDOR_DIR, "systemfonts");
218	
219	function fontconfigFile() {
220	  const dir = path.join(os.tmpdir(), "edfringe-req-fontconfig");
221	  const cache = path.join(dir, "cache");
222	  fs.mkdirSync(cache, { recursive: true });
223	  const alias = (from, to) =>
224	    `  <alias binding="strong"><family>${from}</family><prefer><family>${to}</family></prefer></alias>`;
225	  const conf = `<?xml version="1.0"?>
226	<!DOCTYPE fontconfig SYSTEM "urn:fontconfig:fonts.dtd">
227	<fontconfig>
228	  <dir>${SYSTEM_FONTS_DIR}</dir>
229	  <cachedir>${cache}</cachedir>
230	${[
231	  alias("sans-serif", "DejaVu Sans"),
232	  alias("serif", "DejaVu Sans"),
233	  alias("monospace", "DejaVu Sans"),
234	  alias("system-ui", "DejaVu Sans"),
235	  alias("emoji", "Noto Color Emoji"),
236	  // The product's metric-matched fallback faces are `src: local("Arial")`.
237	  alias("Arial", "Liberation Sans"),
238	  alias("Helvetica", "Liberation Sans"),
239	].join("\n")}
240	</fontconfig>
241	`;
242	  const file = path.join(dir, "fonts.conf");
243	  fs.writeFileSync(file, conf);
244	  return file;
245	}
246	
247	let browserPromise = null;
248	
249	async function launchBrowser() {
250	  if (!browserPromise) {
251	    browserPromise = (async () => {
252	      const version = playwrightVersion();
253	      if (version && version !== PINNED_PLAYWRIGHT) {
254	        throw new Error(
255	          `Playwright ${version} found, but the goldens are rendered with ${PINNED_PLAYWRIGHT}. ` +
256	            "Rendering with a different Chromium makes every pixel comparison meaningless — install the pinned version."
257	        );
258	      }
259	      const { chromium } = await loadPlaywright();
260	      return chromium.launch({
261	        env: { ...process.env, FONTCONFIG_FILE: fontconfigFile() },
262	        args: [
263	          "--font-render-hinting=none",
264	          "--force-color-profile=srgb",
265	          "--disable-lcd-text",
266	          "--hide-scrollbars",
267	          // Shadow/blur rasterisation varies run-to-run without these: partial
268	          // raster reuses tiles whose seams land in blur corners.
269	          "--disable-partial-raster",
270	          "--disable-skia-runtime-opts",
271	          "--disable-gpu",
272	        ],
273	      });
274	    })();
275	  }
276	  return browserPromise;
277	}
278	
279	async function closeBrowser() {
280	  if (browserPromise) {
281	    const b = await browserPromise;
282	    await b.close();
283	    browserPromise = null;
284	  }
285	}
286	
287	/**
288	 * A fresh, fully-faked page for one case.
289	 * opts:
290	 *   viewport   "mobile" (default) | "desktop"
291	 *   dataDir    fixture data root (defaults to the committed snapshot)
292	 *   geolocation  override the fixed fake location, or null for "denied"
293	 *   localStorage {key: value} seeded on the fake origin before any page script
294	 *   nowUtcMs   override the pinned instant (rarely; the reference time is shared)
295	 */
296	async function newPage(opts = {}) {
297	  const browser = await launchBrowser();
298	  const geolocation = opts.geolocation === undefined ? GEOLOCATION : opts.geolocation;
299	  const context = await browser.newContext({
300	    viewport: VIEWPORTS[opts.viewport || "mobile"],
301	    deviceScaleFactor: 1,
302	    locale: LOCALE,
303	    // The device's zone. Overridable so a case can prove the product reads
304	    // Edinburgh's clock rather than the device's — a context's zone is fixed at
305	    // creation, so showing two zones means two pages.
306	    timezoneId: opts.timezone || TIMEZONE,
307	    ...(geolocation
308	      ? { geolocation, permissions: ["geolocation"] }
309	      : { permissions: [] }),
310	  });
311	  await routeAll(context, {
312	    dataDir: opts.dataDir || path.join(FIXTURES_DIR, "data"),
313	    failData: opts.failData,
314	  });
315	
316	  const page = await context.newPage();
317	  const now = opts.nowUtcMs || REFERENCE_NOW_UTC_MS;
318	  if (opts.advanceableClock) {
319	    // Time still stands still, but the page's timers exist and can be wound
320	    // forward deliberately (page.clock.fastForward) — how a case proves
321	    // something the passage of time is supposed to change.
322	    await page.clock.install({ time: now });
323	    await page.clock.pauseAt(now);
324	  } else {
325	    await page.clock.setFixedTime(now);
326	  }
327	  await page.addInitScript(SEEDED_RANDOM);
328	  // The CSS freeze can't stop Web Animations API animations (the planner's
329	  // FLIP board diff) — stub element.animate so every WAAPI animation lands on
330	  // its end state instantly.
331	  await page.addInitScript(`
332	    Element.prototype.animate = function () {
333	      const anim = {
334	        finished: Promise.resolve(),
335	        onfinish: null,
336	        cancel() {}, finish() {}, play() {}, pause() {}, reverse() {},
337	        addEventListener(type, fn) { if (type === "finish") setTimeout(fn, 0); },
338	        removeEventListener() {},
339	      };
340	      setTimeout(() => { if (typeof anim.onfinish === "function") anim.onfinish(); }, 0);
341	      return anim;
342	    };
343	  `);
344	  await page.addInitScript(
345	    `document.addEventListener("DOMContentLoaded", () => {
346	       const s = document.createElement("style");
347	       s.textContent = ${JSON.stringify(FREEZE_CSS)};
348	       document.head.appendChild(s);
349	     });`
350	  );
351	  if (opts.localStorage) {
352	    await page.addInitScript(
353	      `for (const [k, v] of Object.entries(${JSON.stringify(opts.localStorage)})) localStorage.setItem(k, v);`
354	    );
355	  }
356	  return { page, context, origin: ORIGIN };
357	}
358	
359	module.exports = { newPage, closeBrowser, launchBrowser, ORIGIN, VIEWPORTS, PINNED_PLAYWRIGHT };
