761	const VERIFY = 'scripts/verify.sh';
762	const NORMALIZER = 'scraper/normalize.py';
763	const SELFTEST = '--selftest';
764	
765	// Scoped parse rather than a grep: verify.sh labels the step
766	// `step "Normalizer self-test — normalize.py --selftest"`, so a plain grep for
767	// the two tokens passes even after the real invocation is deleted — the label
768	// alone would satisfy it. Drop comment lines and the quoted argument of every
769	// `step` call, then look for a surviving command line.
770	function commandLines(sh) {
771	  return sh
772	    .split('\n')
773	    .filter((l) => !/^\s*#/.test(l))
774	    .map((l) => l.replace(/\bstep\s+(["'])(?:(?!\1).)*\1/g, ''))
775	    // A trailing comment can carry the tokens too (`node --check  # not normalize.py --selftest`).
776	    .map((l) => l.replace(/\s#.*$/, ''));
777	}
