779	const rule = {
780	  id: 'edfringe-normalizer-selftest-in-verify',
781	  severity: 'blocking',
782	  description: "scripts/verify.sh runs the normalizer's offline self-test (python3 scraper/normalize.py --selftest)",
783	  why:
784	    "the live edfringe API is unreachable from a session, so the normalizer self-test is the ONE transform check that runs offline — drop it from the gate and every scraper change ships with no verification at all, in a repo where nothing else can stand in for it",
