788	    // Relevance-first: no normalizer, or one with no self-test to run, is not
789	    // this rule's business.
790	    if (!ctx.files.includes(NORMALIZER)) return [];
791	    const normalizer = ctx.read(NORMALIZER);
792	    if (normalizer === null || !normalizer.includes(SELFTEST)) return [];
