1	// Post-hoc enforcement of a task's declared outcome ceiling (per-project-scheduling
2	// DESIGN §1, §5.5). The executor runs this in code AFTER the subagent finishes:
3	// the outcome is a ceiling enforced, not merely requested in prose, so a `none`
4	// task that opened a PR — or an `open-pr` task that merged one — fails the run
5	// and converges to needs-human. "No change" is always legal.
6	//
7	// Pushes to non-default branches (e.g. the conversation-logs prune) are outside
8	// the PR taxonomy (DESIGN §1) and are not judged here — the caller passes only
9	// what the task did to PULL REQUESTS.
10	
11	import { OUTCOMES } from './task-contract.mjs';
12	
13	// Verify what a task actually did against its declared ceiling.
14	//   outcome    — the task's declared ceiling ('none' | 'open-pr' | 'merged-pr')
15	//   openedPr   — did the run open a pull request?
16	//   mergedPr   — did the run merge (or arm auto-merge on) a pull request?
17	// Returns { ok, violation } — violation is null when within the ceiling.
18	export function verifyOutcome({ outcome, openedPr = false, mergedPr = false }) {
19	  if (!OUTCOMES.includes(outcome)) {
20	    return { ok: false, violation: `unknown outcome ceiling "${outcome}"` };
21	  }
22	  // Merging implies a PR exists; treat a merge as also having opened one so a
23	  // caller that only reports mergedPr is still judged correctly.
24	  const opened = openedPr || mergedPr;
25	
26	  if (outcome === 'none' && opened) {
27	    return { ok: false, violation: 'a "none" task must not open or merge a pull request' };
28	  }
29	  if (outcome === 'open-pr' && mergedPr) {
30	    return { ok: false, violation: 'an "open-pr" task must not merge a pull request' };
31	  }
32	  return { ok: true, violation: null };
33	}
34

